    potential_roots = [1, -1]
    for i in range(2, int(math.sqrt(len(xs))) + 1):
        if len(xs) % i == 0:
            potential_roots.extend([i, -i])
    for root in potential_roots:
        if abs(poly(xs, root)) < 1e-6:
            return root
    # If no root is found, use Newton's method to find a root
    def newton_method(f, df, x0, tol=1e-6, max_iter=100):
        x = x0
        for i in range(max_iter):
            x_next = x - f(x) / df(x)
            if abs(x_next - x) < tol:
                return x_next
            x = x_next
        return x
    # Define the polynomial and its derivative
    def f(x):
        return poly(xs, x)
    def df(x):
        return (poly(xs, x + 1e-6) - poly(xs, x - 1e-6)) / 2e-6
    # Find a root using Newton's method
    return newton_method(f, df, 0)

